"""Download the PAWL reference implementation at its pinned commit.

``vendor/partial.py`` is **not** redistributed with this repository: the upstream
project (https://github.com/rtavenar/partial_ot_1d) carries no licence file, so
copying the file into a third-party repository would be a redistribution we have
no permission for.  Fetching it from upstream on your own machine is fine, so
this script does that and checks the result against the SHA-256 recorded in
``vendor/checksums.txt``.

The file is only needed for the *baselines*: ``pawc.baseline_cuts`` (the
cut-enumeration reference solver) and the PAWL curve in
``demos/demo2_scaling.py``.  PAWC itself --- ``pawc.pawc``,
``pawc.pawc_reference``, ``pawc.pawc_numba`` --- has no dependency on it.

Usage
-----
    python vendor/fetch_pawl.py
    python vendor/fetch_pawl.py --check     # verify an existing copy, download nothing
"""

from __future__ import annotations

import argparse
import hashlib
import sys
import urllib.request
from pathlib import Path

#: Pinned in vendor/PROVENANCE.md.  Do not float this to a branch name: the
#: recorded checksum, and every baseline number in the paper, refer to this tree.
COMMIT = "849e82e57b95d9de0db9884ba397d5b4d9d0b0e0"
URL = f"https://raw.githubusercontent.com/rtavenar/partial_ot_1d/{COMMIT}/partial.py"

HERE = Path(__file__).resolve().parent
TARGET = HERE / "partial.py"
CHECKSUMS = HERE / "checksums.txt"


def expected_sha256() -> str:
    for line in CHECKSUMS.read_text().splitlines():
        line = line.strip()
        if line.endswith("vendor/partial.py"):
            return line.split()[0]
    raise SystemExit(f"no entry for vendor/partial.py in {CHECKSUMS}")


def verify(path: Path) -> bool:
    got = hashlib.sha256(path.read_bytes()).hexdigest()
    want = expected_sha256()
    if got == want:
        print(f"ok  {path}  sha256={got}")
        return True
    print(f"MISMATCH  {path}\n  expected {want}\n  got      {got}", file=sys.stderr)
    return False


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--check", action="store_true", help="verify only, do not download")
    args = ap.parse_args()

    if args.check:
        if not TARGET.exists():
            print(f"missing {TARGET}; run `python vendor/fetch_pawl.py`", file=sys.stderr)
            return 1
        return 0 if verify(TARGET) else 1

    if TARGET.exists():
        print(f"{TARGET} already present; verifying")
        return 0 if verify(TARGET) else 1

    print(f"fetching {URL}")
    with urllib.request.urlopen(URL, timeout=60) as resp:  # noqa: S310 (fixed https URL)
        data = resp.read()
    TARGET.write_bytes(data)
    if not verify(TARGET):
        TARGET.unlink()
        print("deleted the bad download", file=sys.stderr)
        return 1
    print(
        "\nPAWL is Chapel & Tavenard, ICLR 2025 -- please cite it if you use the\n"
        "baselines.  See vendor/PROVENANCE.md.  Do not edit this file."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
